var NUN_INDEX = (function(){ var m={}; for (var i=0;i<NUN_CODIGOS.length;i++) m[NUN_CODIGOS[i].codigo]=NUN_CODIGOS[i]; return m; })();

// Normaliza 'ms 4 1', 'MS0401', 'ms.4.1' -> 'MS.04.01'. Devuelve null si no matchea.
function nunNormalizarCodigo(raw){
  if(!raw) return null;
  var s=String(raw).toUpperCase().replace(/\s+/g,'');
  var m=s.match(/^([A-Z]{2})[.\-]?(\d{1,2})[.\-]?(\d{1,2})$/);
  if(!m) return null;
  var reg=m[1];
  if(!NUN_REGIONES[reg]) return null;
  return reg+'.'+('0'+m[2]).slice(-2)+'.'+('0'+m[3]).slice(-2);
}

function nunBuscar(raw){
  var cod=nunNormalizarCodigo(raw);
  return cod ? (NUN_INDEX[cod]||null) : null;
}

// Describe un código para mostrar en la UI: 'MS.06.02 — C6 Miembro superior — Fracturas del radio distal…'
function nunDescribir(raw){
  var e=nunBuscar(raw);
  if(!e) return null;
  return e.codigo+' — C'+e.complejidad+' '+NUN_REGIONES[e.region]+' — '+e.texto;
}

if (typeof window !== 'undefined') { window.NUN_CODIGOS=NUN_CODIGOS; window.NUN_INDEX=NUN_INDEX; window.NUN_NORMAS=NUN_NORMAS; window.NUN_REGIONES=NUN_REGIONES; window.nunBuscar=nunBuscar; window.nunDescribir=nunDescribir; window.nunNormalizarCodigo=nunNormalizarCodigo; }
